// 紧凑构建索引（量级可控，启动期阻塞极短）
window.WUBI_INDEX = (function () {
  var idx = {};
  window.WUBI_RAW.forEach(function (line) {
    var p = line.split(' '), code = p[0], f = parseInt(p[p.length - 1], 10), t = p.slice(1, -1).join(' ');
    (idx[code] = idx[code] || []).push({ t: t, f: f });
  });
  return idx;
})();
